import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate d = LocalDate.of(2025, 9, 16);
        LocalDate fine = d.plusMonths(3).withDayOfMonth(1);
        System.out.println(ChronoUnit.DAYS.between(d, fine));
        LocalDateTime dt = LocalDateTime.of(2025, 9, 16, 10, 30);
        System.out.println(dt.format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm")));
        System.out.println(Duration.ofMinutes(135).toHours());
    }
}

