class Conto {
    private double saldo;
    public void deposita(double v) {
        if (v <= 0) throw new IllegalArgumentException("importo non valido");
        saldo += v;
    }
    public double getSaldo() { return saldo; }
}
public class Main {
    public static void main(String[] args) {
        Conto c = new Conto();
        c.deposita(50);
        System.out.println(c.getSaldo());
    }
}

class Contatore {
    static int totale = 0;
    static final double IVA = 0.22;
    Contatore() { totale++; }
    static double conIva(double p) { return p * (1 + IVA); }
}
public class Main {
    public static void main(String[] args) {
        new Contatore();
        new Contatore();
        System.out.println(Contatore.totale);
        System.out.println(Contatore.conIva(100));
    }
}

