    static Saluto di(String n) { return () -> n; }
}

public class Main {
    public static void main(String[] args) {
        Saluto s = Saluto.di("Java");
        System.out.println(s.ciao());
    }
}

import java.util.function.*;

@FunctionalInterface
interface Op { int applica(int a, int b); }

public class Main {
    public static void main(String[] args) {
        Op somma = (a, b) -> a + b;
        Op molt = (a, b) -> a * b;
        System.out.println(somma.applica(2, 3) + " " + molt.applica(2, 3));
        Function<Integer, Integer> doppio = x -> x * 2;
        System.out.println(doppio.apply(21));
    }
}

