record Punto(int x, int y) {
    double dist() { return Math.sqrt(x * x + y * y); }
    static Punto origine() { return new Punto(0, 0); }
}

public class Main {
    public static void main(String[] args) {
        Punto p = new Punto(3, 4);
        System.out.println(p + " " + p.x() + " " + p.dist());
        System.out.println(p.equals(new Punto(3, 4)));
    }
}

record Intervallo(int a, int b) {
    Intervallo {
        if (a > b) throw new IllegalArgumentException("a > b");
    }
    int ampiezza() { return b - a; }
}

public class Main {
    public static void main(String[] args) {
        System.out.println(new Intervallo(2, 9).ampiezza());
        try { new Intervallo(5, 1); }
        catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }
    }
}

sealed interface Forma permits Cerchio, Quadrato { }
record Cerchio(double r) implements Forma { }
record Quadrato(double l) implements Forma { }

public class Main {
    public static void main(String[] args) {
        Forma f = new Cerchio(1);
        System.out.println(f instanceof Cerchio);
        System.out.println(Forma.class.isSealed());
    }
}

sealed interface Forma permits Cerchio, Quadrato { }
record Cerchio(double r) implements Forma { }
record Quadrato(double l) implements Forma { }
public class Main {
    static double area(Forma f) {
        return switch (f) {
            case Cerchio c -> Math.PI * c.r() * c.r();
            case Quadrato q -> q.l() * q.l();
        };
    }
    public static void main(String[] args) {
        System.out.println(area(new Quadrato(3)));
    }
}

record Punto(int x, int y) { }
record Linea(Punto a, Punto b) { }
public class Main {
    static String descrivi(Object o) {
        return switch (o) {
            case Linea(Punto(var x1, var y1), Punto p2) when x1 == p2.x() -> "verticale";
            case Linea(Punto a, Punto b) -> "linea";
            case Punto(int x, int y) -> "punto " + (x + y);
            default -> "altro";
        };
    }
    public static void main(String[] args) {
        System.out.println(descrivi(new Linea(new Punto(1, 2), new Punto(1, 5))));
    }
}
